
class SubtitleCue { final Duration start; final Duration end; final String text; final String? style; const SubtitleCue(this.start,this.end,this.text,{this.style}); }
class SubtitleTrackData { final List<SubtitleCue> cues; const SubtitleTrackData(this.cues); SubtitleCue? cueAt(Duration t)=> cues.where((c)=> t>=c.start && t<=c.end).firstOrNull; List<SubtitleCue> cuesIn(Duration a,Duration b)=> cues.where((c)=> c.end>=a && c.start<=b).toList(); }
Duration _parseTs(String s){ s=s.trim().replaceAll('.',','); final parts=s.split(':'); if(parts.length==3){ final sec=parts[2].split(','); return Duration(hours:int.parse(parts[0]),minutes:int.parse(parts[1]),seconds:int.parse(sec[0]),milliseconds: sec.length>1?int.parse(sec[1].padRight(3,'0').substring(0,3)):0);} if(parts.length==2){ final sec=parts[1].split(','); return Duration(minutes:int.parse(parts[0]),seconds:int.parse(sec[0]),milliseconds: sec.length>1?int.parse(sec[1].padRight(3,'0').substring(0,3)):0);} return Duration.zero; }
Duration _assTs(String s){ final p=s.trim().split(':'); final sec=p[2].split('.'); return Duration(hours:int.parse(p[0]),minutes:int.parse(p[1]),seconds:int.parse(sec[0]),milliseconds:int.parse(sec[1].padRight(3,'0').substring(0,3))*10 ~/10); }
class SrtParser { static SubtitleTrackData parse(String input){ final cues=<SubtitleCue>[]; final blocks=input.replaceAll('\r\n','\n').split(RegExp(r'\n\s*\n')); for(final b in blocks){ final lines=b.trim().split('\n'); if(lines.isEmpty) continue; final idx=lines.indexWhere((l)=>l.contains('-->')); if(idx<0) continue; final times=lines[idx].split('-->'); final text=lines.sublist(idx+1).join('\n').trim(); if(text.isEmpty) continue; cues.add(SubtitleCue(_parseTs(times[0]),_parseTs(times[1].trim().split(' ').first),text)); } cues.sort((a,b)=>a.start.compareTo(b.start)); return SubtitleTrackData(cues); } }
class VttParser { static SubtitleTrackData parse(String input){ var s=input; if(s.startsWith('WEBVTT')) s=s.substring(s.indexOf('\n')+1); final cues=<SubtitleCue>[]; final blocks=s.replaceAll('\r\n','\n').split(RegExp(r'\n\s*\n')); for(final b in blocks){ final lines=b.trim().split('\n'); final idx=lines.indexWhere((l)=>l.contains('-->')); if(idx<0) continue; final times=lines[idx].split('-->'); final text=lines.sublist(idx+1).join('\n').replaceAll(RegExp(r'<[^>]+>'),'').trim(); if(text.isEmpty) continue; cues.add(SubtitleCue(_parseTs(times[0]),_parseTs(times[1].trim().split(' ').first),text)); } cues.sort((a,b)=>a.start.compareTo(b.start)); return SubtitleTrackData(cues); } }
class AssParser { static SubtitleTrackData parse(String input){ final cues=<SubtitleCue>[]; for(final line in input.split('\n')){ if(!line.startsWith('Dialogue:')) continue; final parts=line.substring(9).split(','); if(parts.length<10) continue; final start=_assTs(parts[1]); final end=_assTs(parts[2]); final style=parts[3].trim(); var text=parts.sublist(9).join(',').replaceAll(r'\N','\n').replaceAll(RegExp(r'\{[^}]*\}'),''); cues.add(SubtitleCue(start,end,text,style:style.isEmpty?null:style)); } cues.sort((a,b)=>a.start.compareTo(b.start)); return SubtitleTrackData(cues); } }
SubtitleTrackData parseSubtitle(String format,String input){ switch(format.toLowerCase()){ case 'vtt': return VttParser.parse(input); case 'ass': case 'ssa': return AssParser.parse(input); default: return SrtParser.parse(input); } }
